#include <stdint.h>
#include <stdio.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
#warning                                                                       \
    "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void delay(void) {
    for(volatile uint32_t i=0; i < 300000; i++);
}

// Short pause after changing which row is driven low, before reading columns.
// The column needs time to climb back to 3.3V; reading immediately can still
// see the previous row's low and report the wrong key.
void settle(void) {
    for(volatile uint32_t i=0; i < 500; i++);
}

int main(void) {
  // Enable the FPU: CPACR bits [23:20] = full access to CP10/CP11.
  // Project builds hard-float but nothing calls SystemInit, so the FPU is off
  // and any VFP instruction (printf pulls some in) faults as UNDEFINSTR.
  *((volatile uint32_t *)0xE000ED88) |= (0xF << 20);
  __asm volatile("dsb");
  __asm volatile("isb");

  uint32_t volatile *const pClockCtrlReg = (uint32_t *)(0x40023800 + 0x30);
  uint32_t volatile *const pGPIODModeReg = (uint32_t *)(0x40020C00 + 0x00);
  uint32_t volatile *const pPullupDownReg = (uint32_t *)(0x40020C00 + 0x0C);
  uint32_t volatile *const pInPutDataReg = (uint32_t *)(0x40020C00 + 0x10);
  uint32_t volatile *const pOutPutDataReg = (uint32_t *)(0x40020C00 + 0x14);

  // 1. Enable the peripheral clock of GPIOD peripheral (port D is bit 3)
  *pClockCtrlReg |= (1 << 3);

  // 2. configure PD0, PD1, PD2, PD3 as output (rows)
  // MODER is 2 bits per pin: pin n is bits [2n+1:2n]. clear 0x3, then set 0x1
  // (output)
  *pGPIODModeReg &= ~(0x3 << 0);
  *pGPIODModeReg |= (0x1 << 0);
  *pGPIODModeReg &= ~(0x3 << 2);
  *pGPIODModeReg |= (0x1 << 2);
  *pGPIODModeReg &= ~(0x3 << 4);
  *pGPIODModeReg |= (0x1 << 4);
  *pGPIODModeReg &= ~(0x3 << 6);
  *pGPIODModeReg |= (0x1 << 6);

  // tutorial's version
  // *pGPIODModeReg &= ~(0xFF); // clear
  // *pGPIODModeReg |= 0x55; // set

  // 3. configure PD8, PD9, PD10, PD11 as input (columns)
  // input is 00, so clearing each field is the whole job - no set step
  *pGPIODModeReg &= ~(0x3 << 16);
  *pGPIODModeReg &= ~(0x3 << 18);
  *pGPIODModeReg &= ~(0x3 << 20);
  *pGPIODModeReg &= ~(0x3 << 22);

  // tutorial version
  // *pGPIODModeReg &= ~(0xFF << 16);

  // 4. Enable internal pull-up resistors for PD8, PD9, PD10, PD11
  // PUPDR is also 2 bits per pin. 01 = pull-up
  // clear
  *pPullupDownReg &= ~(0x3 << 16);
  *pPullupDownReg &= ~(0x3 << 18);
  *pPullupDownReg &= ~(0x3 << 20);
  *pPullupDownReg &= ~(0x3 << 22);
  // set
  *pPullupDownReg |= (0x1 << 16);
  *pPullupDownReg |= (0x1 << 18);
  *pPullupDownReg |= (0x1 << 20);
  *pPullupDownReg |= (0x1 << 22);

  // tutorial version
  // *pPullupDownReg &= ~(0xFF << 16); // clear
  // *pPullupDownReg |= (0x55 << 16); // set

  // 5. Make all rows HIGH. ODR is 1 bit per pin, so PD0-PD3 is 0xF
  *pOutPutDataReg |= (0xF);

  printf("boot\n"); // TEMP diagnostic - remove once trace is confirmed

  while (1) {
    // Make all rows HIGH. This has to happen every pass: R4 is left low at the
    // end of the loop body, so without it the R1 scan runs with R4 also low and
    // row-4 presses get reported as row-1 keys.
    *pOutPutDataReg |= (0xF);

    // Make R1 LOW (PD0)
    *pOutPutDataReg &= ~(1 << 0);
    settle();

    // scan the columns - pull-up means idle reads 1, a pressed key reads 0
    if (!(*pInPutDataReg & (1 << 8))) {
      delay();
      printf("1\n");
    }
    if (!(*pInPutDataReg & (1 << 9))) {
      delay();
      printf("2\n");
    }
    if (!(*pInPutDataReg & (1 << 10))) {
      delay();
      printf("3\n");
    }
    if (!(*pInPutDataReg & (1 << 11))) {
      delay();
      printf("A\n");
    }

    // Make R2 LOW (PD1)
    *pOutPutDataReg |= (0xF); // make all rows high
    *pOutPutDataReg &= ~(1 << 1);
    settle();

    // scan the columns - pull-up means idle reads 1, a pressed key reads 0
    if (!(*pInPutDataReg & (1 << 8))) {
      delay();
      printf("4\n");
    }
    if (!(*pInPutDataReg & (1 << 9))) {
      delay();
      printf("5\n");
    }
    if (!(*pInPutDataReg & (1 << 10))) {
      delay();
      printf("6\n");
    }
    if (!(*pInPutDataReg & (1 << 11))) {
      delay();
      printf("B\n");
    }

    // Make R3 LOW (PD2)
    *pOutPutDataReg |= (0xF); // make all rows high
    *pOutPutDataReg &= ~(1 << 2);
    settle();

    // scan the columns - pull-up means idle reads 1, a pressed key reads 0
    if (!(*pInPutDataReg & (1 << 8))) {
      delay();
      printf("7\n");
    }
    if (!(*pInPutDataReg & (1 << 9))) {
      delay();
      printf("8\n");
    }
    if (!(*pInPutDataReg & (1 << 10))) {
      delay();
      printf("9\n");
    }
    if (!(*pInPutDataReg & (1 << 11))) {
      delay();
      printf("C\n");
    }

    // Make R4 LOW (PD3)
    *pOutPutDataReg |= (0xF); // make all rows high
    *pOutPutDataReg &= ~(1 << 3);
    settle();

    // scan the columns - pull-up means idle reads 1, a pressed key reads 0
    if (!(*pInPutDataReg & (1 << 8))) {
      delay();
      printf("*\n");
    }
    if (!(*pInPutDataReg & (1 << 9))) {
      delay();
      printf("0\n");
    }
    if (!(*pInPutDataReg & (1 << 10))) {
      delay();
      printf("#\n");
    }
    if (!(*pInPutDataReg & (1 << 11))) {
      delay();
      printf("D\n");
    }
  }

  /* Loop forever */
  for (;;)
    ;
}
